  'workflows-p4' => 'Փաստաթղթերի մեծ հավաքածուներից տեքստ հանող թիմերն օգտվում են OCR ավտոմատացումից: Երբ OCR-ն ավարտվում է, փաստաթղթերը կազմակերպման և ձևաչափման կարիք ունեն: __MERGE_LINK__ առնչվող փաստաթղթերը վերածվում են կազմակերպված հավաքածուների, այնուհետև __CONVERT_LINK__՝ խմբագրվող ձևաչափերի, ինչը հնարավորություն է տալիս ավելի հեշտ մշակել և վերլուծել: Ավտոմատացված աշխատանքային հոսքը կարող է տեքստ հանել հարյուրավոր սկանավորված հաշիվ-ապրանքագրերից, այնուհետև դրանք միավորել կազմակերպված ամսական խմբաքանակների, այնուհետև ավտոմատ կերպով վերածել աղյուսակների համար հարմար ձևաչափի:',
  'accuracy-heading' => 'Ճշգրտության ակնկալիքներ',
  'accuracy-p1' => 'Բարձրորակ տպագիր փաստաթղթերը հասնում են իննսունհինգից իննսունութ տոկոս ճշգրտության: Սա նշանակում է մեկից հինգ սխալ հարյուր բառի համար: Ձեռքով սրբագրումը արագորեն հայտնաբերում է մնացած սխալները:',
  'accuracy-p2' => 'Միջին որակի փաստաթղթերը հասնում են ութսունհինգից իննսունհինգ տոկոս ճշգրտության: Պահանջվում է ավելի շատ սրբագրում, բայց դեռ ավելի արագ, քան ձեռքով տվյալների մուտքագրումը:',
  'accuracy-p3' => 'Անորակ կամ ձեռագիր փաստաթղթերը հասնում են վաթսունից ութսուն տոկոս ճշգրտության: Պահանջվում է լայնածավալ սրբագրում: Հաճախ ավելի արագ է ձեռքով մուտքագրելը, քան սխալ OCR արդյունքները սրբագրելը:',
  'accuracy-p4' => 'Միշտ պլանավորեք սրբագրման համար: Նույնիսկ բարձր ճշգրտության OCR-ն սխալներ է թույլ տալիս: Ֆինանսական փաստաթղթերը պահանջում են ամբողջական ստուգում: Իրավական փաստաթղթերը պահանջում են մանրակրկիտ վերանայում:',
  'difficult-heading' => 'Դժվար փաստաթղթերի մշակում',
  'difficult-p1' => 'Ձեռագիր տեքստը զգալիորեն նվազեցնում է OCR-ի ճշգրտությունը: Ձեռագրի ճանաչման մասնագիտացված գործիքները ավելի լավ արդյունքների են հասնում, քան ընդհանուր OCR-ն, սակայն դեռևս պահանջում են սրբագրում:',
  'difficult-p2' => 'Գունավոր տեքստը և անսովոր ձևաչափումը շփոթեցնում են OCR-ին: Բարձրացրեք հակադրությունը և պարզեցրեք ձևաչափումը, եթե հնարավոր է, նախքան OCR մշակումը:',
  'difficult-p3' => 'Ոչ ստանդարտ տառատեսակները նվազեցնում են ճշգրտությունը: Եթե ​​հնարավոր է, նորից սկանավորեք փաստաթղթերը ավելի բարձր լուծաչափով կամ օգտագործեք մասնագիտացված տառատեսակներ, որոնք OCR-ն ավելի լավ է ճանաչում:',
  'difficult-p4' => 'Բազմալեզու փաստաթղթերին անհրաժեշտ է լեզվին հատուկ OCR: Անգլերենն ու իսպաներենը խառնող փաստաթղթերին անհրաժեշտ է երկու լեզուների համար կազմաձևված OCR:',
  'postocr-heading' => 'Հետ OCR մշակում',
  'postocr-p1' => 'OCR-ի ավարտից հետո ստացված տեքստային ֆայլը սովորաբար մաքրման կարիք ունի: Հատուկ նիշերը կարող են սխալ նույնականացվել: Ֆորմատավորումը կարող է ճշգրտման կարիք ունենալ:',
  'postocr-p2' => 'Օգտագործեք «գտնել և փոխարինել» գործառույթները՝ սովորական սխալները շտկելու համար: Եթե ​​OCR-ը մշտապես սխալ է նույնականացնում կոնկրետ բառը, գտեք և փոխարինեք բոլոր օրինակները:',
  'postocr-p3' => 'Ձեռքով վերանայեք կարևոր բաժինները: Ֆինանսական փաստաթղթերի համար ստուգեք բոլոր համարները: Իրավական փաստաթղթերի համար ստուգեք անունները և ամսաթվերը:',
  'postocr-p4' => 'Պատշաճ ձևաչափեք տեքստը: OCR-ը կարող է կորցնել պարբերության ընդմիջումները կամ տարածությունները: Վերափոխել ընթեռնելի կառուցվածքի:',
  'optimization-heading' => 'OCR-ի կատարողականի օպտիմիզացում',
  'optimization-p1' => 'Փաստաթղթերը մշակեք խմբաքանակով, այլ ոչ թե առանձին: Խմբաքանակի մշակումն ավելի արդյունավետ և ավելի էժան է յուրաքանչյուր փաստաթղթի համար:',
  'optimization-p2' => 'Անորակ փաստաթղթերը մշակեք առանձին: Մի խառնեք բարձրորակ և ցածրորակ փաստաթղթերը նույն խմբաքանակում, քանի որ դուք պետք է սահմանեք ստանդարտ OCR որակ, որը չի օպտիմիզացված ոչ մեկի համար:',
  'optimization-p3' => 'Սեղմեք OCR արդյունքները՝ պահեստավորման պահանջները նվազեցնելու համար: Որոնվող PDF ֆայլերն ավելի մեծ են, քան պատկերները: Սեղմումը խնայում է պահեստավորումը՝ չկորցնելով տեքստի որոնելիությունը:',
  'optimization-p4' => 'Ստուգումից հետո ջնջեք բնօրինակ սկանավորումները: Երբ OCR-ն ավարտված և հաստատված է, բնօրինակ պատկերները կարող են ջնջվել՝ պահեստը խնայելու համար:',
  'trends-heading' => 'OCR տեխնոլոգիայի միտումները',
  'trends-p1' => 'AI-ն և մեքենայական ուսուցումը շարունակում են բարելավել OCR-ի ճշգրտությունը: Ժամանակակից գործիքները հասնում են արդյունավետության, որը գերազանցում է մարդկանց շատ սցենարներում:',
  'trends-p2' => 'Իրական ժամանակի OCR-ն սովորական է դառնում: Սմարթֆոնների տեսախցիկները կարող են ակնթարթորեն տեքստ հանել փաստաթղթերից: Կենդանի թարգմանությունն ապահովված է իրական ժամանակի OCR-ով:',
  'trends-p3' => 'Համատեքստային ըմբռնումը բարելավում է ճշգրտությունը: Ժամանակակից OCR-ը ոչ միայն ճանաչում է տառերը, այլ հասկանում է իմաստը՝ բարելավելով երկիմաստ դեպքերի ճշգրտությունը:',
  'trends-p4' => 'Բազմալեզու աջակցությունը բարելավվում է: OCR-ը, որը միաժամանակ փաստաթղթեր է մշակում բազմաթիվ լեզուներով, դառնում է գործնական:',
  'conclusion-heading' => 'Եզրակացություն',
  'conclusion-p1' => 'OCR տեխնոլոգիան սկանավորված փաստաթղթերը վերածում է որոնելի, խմբագրելի տեքստի: Ժամանակակից AI-ով աշխատող OCR-ը որակյալ սկանավորումների դեպքում հասնում է իննսունհինգ տոկոսից ավելի ճշգրտության:',
  'conclusion-p2' => 'OCR որակը գնահատելու համար սկսեք առանձին փաստաթղթերից: Իրականացնել խմբաքանակի մշակում փաստաթղթերի ծավալների համար: Ավտոմատացրեք OCR-ի աշխատանքային հոսքերը ընթացիկ գործողությունների համար:',
  'conclusion-p3' => 'Պլանավորեք սրբագրումը ձեր OCR-ի աշխատանքային հոսքերում: Նույնիսկ բարձր ճշգրտության OCR-ն պահանջում է կարևոր տեղեկատվության ստուգում:',
  'conclusion-p4' => 'Միավորել OCR-ն այլ PDF գործիքների հետ՝ փաստաթղթերի ամբողջական աշխատանքային հոսքերի համար: Արդյունահանման, փոխակերպման և կազմակերպման գործիքների ինտեգրումը ստեղծում է փաստաթղթերի կառավարման համապարփակ լուծումներ:',
);
